:root {
  font-family: 'DM Sans', system-ui, sans-serif;
  color: #232720;
  background: #f7f6f2;
  font-synthesis: none;
  --green: #2e6f65;
  --green-dark: #245c54;
  --line: #e4e3dd;
  --muted: #7c8078;
  --sidebar: 244px;
}
* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; min-height: 100vh; background: #f7f6f2; }
button, input, textarea, select { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
button { cursor: pointer; }
.app-shell { min-height: 100vh; }
.topbar { height: 76px; background: rgba(255,255,255,.94); border-bottom: 1px solid var(--line); position: fixed; z-index: 30; inset: 0 0 auto 0; display: grid; grid-template-columns: var(--sidebar) minmax(280px, 560px) 1fr; align-items: center; padding: 0 34px 0 28px; gap: 48px; backdrop-filter: blur(12px); }
