kbd { border: 1px solid #deded8; background: #fff; border-radius: 5px; color: #92958e; padding: 2px 6px; font: 500 11px 'DM Sans'; box-shadow: 0 1px 0 #d6d6d0; }
.top-actions { margin-left: auto; display: flex; align-items: center; gap: 20px; }
.btn { border: 0; border-radius: 10px; min-height: 42px; padding: 0 17px; display: inline-flex; align-items: center; justify-content: center; gap: 8px; font-weight: 600; font-size: 14px; transition: transform .15s, background .15s, box-shadow .15s; }
