.modal-actions { padding-top: 5px; display: flex; justify-content: flex-end; gap: 9px; }
.toast { position: fixed; z-index: 120; left: 50%; bottom: 28px; transform: translateX(-50%); background: #27302c; color: white; padding: 11px 16px; border-radius: 10px; display: flex; gap: 9px; align-items: center; font-size: 13px; box-shadow: 0 8px 30px rgba(0,0,0,.2); animation: toastIn .25s ease; }
.toast svg { color: #7ed1a1; }
.mobile-menu, .sidebar-mobile-head { display: none; }
@keyframes fadeIn { from { opacity: 0; } }
@keyframes modalIn { from { opacity: 0; transform: translateY(8px) scale(.985); } }
@keyframes toastIn { from { opacity: 0; transform: translate(-50%, 8px); } }
@media (max-width: 1100px) {
  .bookmark-layout.grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .topbar { gap: 20px; }
}
@media (max-width: 780px) {
  :root { --sidebar: 0px; }
  .topbar { height: 68px; padding: 0 18px; grid-template-columns: auto auto minmax(0,1fr) auto; gap: 11px; }
  .mobile-menu { display: grid; }
  .brand span:last-child { display: none; }
  .top-search { grid-column: 3; }
  .top-actions .btn { display: none; }
  .top-actions { margin-left: 0; }
  .sidebar { inset: 0 auto 0 0; width: 270px; transform: translateX(-102%); transition: transform .25s ease; padding-top: 16px; }
  .sidebar-open { transform: none; }
  .sidebar-mobile-head { display: flex; justify-content: space-between; align-items: center; padding: 0 7px 18px 12px; font-weight: 700; }
  .scrim { position: fixed; z-index: 24; inset: 0; background: rgba(30,35,30,.3); }
  .main { margin-left: 0; padding: 68px 20px 50px; }
  .hero { padding-top: 37px; }
  .hero-add { display: inline-flex; }
  .bookmark-layout.list .card-footer { display: none; }
}
@media (max-width: 580px) {
  .topbar { grid-template-columns: auto auto 1fr auto; }
  .top-search { position: absolute; top: 78px; left: 20px; right: 20px; background: white; box-shadow: 0 5px 20px rgba(0,0,0,.08); opacity: 0; pointer-events: none; }
  .hero { padding-top: 30px; align-items: center; }
  .hero h1 { font-size: 28px; }
  .hero p:not(.eyebrow) { max-width: 230px; line-height: 1.5; }
  .hero-add { width: 42px; padding: 0; }
  .hero-add svg { margin: 0; }
  .hero-add { font-size: 0; }
  .bookmark-layout.grid { grid-template-columns: 1fr; }
  .toolbar { height: 72px; }
  .sort-control > span { display: none; }
  .bookmark-layout.list .bookmark-card { grid-template-columns: 44px minmax(0,1fr) auto; min-height: 92px; padding: 14px; }
  .bookmark-layout.list .site-icon { width: 38px; height: 38px; }
  .bookmark-layout.list .card-copy p, .bookmark-layout.list .domain { display: none; }
  .form-row { grid-template-columns: 1fr; gap: 0; }
  .modal { max-height: 94vh; overflow-y: auto; }
  .modal-head, .modal form { padding-left: 20px; padding-right: 20px; }
}

